head.script:
// 데이터/옵션 분리: JSON 은 순수 데이터만, 아래 type+옵션은 스크립트가 보유 → 렌더시 조합
scwin.CHART_TYPE = "gaugeNew";                    // 차트 타입 (스크립트)
scwin.CHART_DATA_URL ="/ui/sample/SBChart/CIRCLE/data/CIRCLE.json";             // 순수 데이터 JSON (type 없음)
scwin.CHART_CONFIG = {
  "global": {   // 전역 설정(색/크기/애니메이션/이벤트)
    "size": {   // 차트 크기
      "width": 500,   // 너비(px 또는 비율)
      "height": 500   // 높이(px)
    }
  },
  "legend": {   // 범례
    "show": false   // 표시 여부
  },
  "tooltip": {   // 툴팁
    "show": true,   // 표시 여부
    "grouped": false,   // 시리즈 묶음 표시
    "format": {   // 표시 형식(포맷 함수)
      "name": function(value, ratio, id, index){   // 이름
				return '속도';
			},
      "value": function(value, ratio, id, index){   // 값 필드
				return value + 'km/h';
			}
    },
    "mouse": {
      "y": 5,
      "x": 0
    }
  },
  "extend": {   // 차트별 세부 옵션
    "gaugeNew": {   // 신형 게이지 전용 옵션
      "userRadius": 190,   // 사용자 반지름
      "innerRadius": 170,   // 안쪽 반지름(도넛 두께)
      "startAngle": -130,   // 시작 각도
      "endAngle": 130,   // 끝 각도
      "min": 0,   // 최소값
      "max": 100,   // 최대값
      "fullCircle": true,   // 완전 원 여부
      "mainCircle": {
        "show": true,   // 표시 여부
        "strokeWidth": 0,   // 선 두께
        "circleType": "single",
        "strokeColor": "pink",   // 선 색
        "fillColor": "#EEEEEE",   // 채움 색
        "useGradation": false,   // 그라데이션 사용
        "cornerRadius": 30   // 모서리 둥글기
      },
      "subCircle": {
        "show": false,   // 표시 여부
        "cornerRadius": 30   // 모서리 둥글기
      },
      "ticks": {
        "majorTicks": {
          "show": true,   // 표시 여부
          "style": "line",
          "length": 12,
          "startPosition": 25,   // 시작 위치
          "interval": 10,   // 간격
          "strokeWidth": 1,   // 선 두께
          "strokeColor": "black",   // 선 색
          "fillColor": "red",   // 채움 색
          "showLabel": true,
          "labelPosition": 50,
          "labelDirection": false,
          "circleRadius": 10   // 원 반지름
        },
        "minorTicks": {
          "show": true,   // 표시 여부
          "style": "line",
          "length": 6,
          "startPosition": 25,   // 시작 위치
          "interval": 2,   // 간격
          "strokeWidth": 1,   // 선 두께
          "strokeColor": "silver",   // 선 색
          "fillColor": "white",   // 채움 색
          "circleRadius": 2   // 원 반지름
        }
      },
      "pointer": {   // 포인터 전용 옵션
        "startPosition": 65,   // 시작 위치
        "length": 145,
        "pointerStyle": {
          "show": true,   // 표시 여부
          "style": "pentagon",
          "strokeWidth": 1,   // 선 두께
          "strokeColor": "#5A5F62",   // 선 색
          "fillColor": "#5A5F62",   // 채움 색
          "opacity": 1,   // 투명도
          "lineCap": "round",
          "midPosition": 130,
          "midWidth": 12,
          "endWidth": 1
        },
        "pointerCircle": {
          "show": true,   // 표시 여부
          "radius": 3,   // 반지름
          "strokeWidth": 1,   // 선 두께
          "strokeColor": "black",   // 선 색
          "fillColor": "white",   // 채움 색
          "opacity": 1,   // 투명도
          "useGradation": false,   // 그라데이션 사용
          "gradationColor": {   // 그라데이션 색
            "direction": "top",
            "startColor": "#FF0000",   // 시작 색
            "endColor": "#FFFFFF"   // 끝 색
          }
        }
      },
      "drawValue": {
        "label": {   // 라벨
          "show": true,   // 표시 여부
          "format": function(v) {   // 표시 형식(포맷 함수)
		  			return v + " km/h";
		  		},
          "posX": 0,
          "posY": 50
        },
        "circle": {
          "show": true,   // 표시 여부
          "strokeWidth": 1,   // 선 두께
          "strokeColor": "white",   // 선 색
          "fillColor": "pink",   // 채움 색
          "opacity": 1   // 투명도
        }
      }
    }
  },
  "dataOpts": {   // 데이터 레벨 옵션(keys/labels 등)
    "labels": false   // 값 라벨 표시
  }
};               // 옵션(global/axis/extend…) + dataOpts(keys/labels…)

scwin.onpageload = async function () {
    const res = await $c.sbm.executeDynamic({ id: "sbm_sbchart", action: scwin.CHART_DATA_URL, method: "get", mediatype: "application/json", mode: "asynchronous", isProcessMsg: false });
    const data = res.responseJSON;
    $c.ext.drawChartData(scwin.CHART_TYPE, data, chartWrap, scwin.CHART_CONFIG);
};
